import csv
import io

_FIELDS = ('sku', 'name', 'qty')
_DECIMAL_DIGITS = set('0123456789')


def _parse_row(row):
    for field in _FIELDS:
        if row.get(field) is None:
            raise ValueError('row is missing %r field: %r' % (field, row))
    if row.get(None) is not None:
        raise ValueError('row has too many fields: %r' % (row,))
    sku = row['sku'].strip()
    name = row['name'].strip()
    qty_text = row['qty'].strip()
    if not sku:
        raise ValueError('sku must not be empty: %r' % (row,))
    if not name:
        raise ValueError('name must not be empty: %r' % (row,))
    if not qty_text or any(ch not in _DECIMAL_DIGITS for ch in qty_text):
        raise ValueError('qty must be a nonnegative integer: %r' % (row,))
    return {'sku': sku, 'name': name, 'qty': int(qty_text)}


def import_text(text, store, dry_run=False):
    # Pass 1: parse and validate every row before committing any changes.
    items = [_parse_row(row) for row in csv.DictReader(io.StringIO(text))]

    # Pass 2: report (and commit unless dry_run) changes in input order.
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)
    return result

